//! Merging entries into a TOML config file without rewriting what is not ours (ADR 0292), on `toml_edit`, which keeps
//! the user's layout, comments and order.
//!
//! An entry is ours when it stands at a place the adapter names (a table and a name, `[mcp_servers.specforge]`) and is a
//! table whose `command` is `specforge`, or a value that carries the [`MARK`] comment
//! (`[features] hooks = true  # generated by specforge install`). A user's own table that also runs `specforge` is not.

use serde_json::Value;
use specforge_ops::host::{Merged, MergedEntry, NotRendered};
use toml_edit::{Array, DocumentMut, InlineTable, Item, Table, Value as Toml};

/// The comment that makes a plain value ours.
pub const MARK: &str = "# generated by specforge install";

fn value(v: &Value) -> Toml {
    match v {
        Value::Bool(b) => Toml::from(*b),
        Value::String(s) => Toml::from(s.as_str()),
        Value::Number(n) => n
            .as_i64()
            .map_or_else(|| Toml::from(n.as_f64().unwrap_or_default()), Toml::from),
        Value::Array(items) => Toml::Array(items.iter().map(value).collect::<Array>()),
        Value::Object(map) => {
            let mut table = InlineTable::new();
            for (k, v) in map {
                table.insert(k, value(v));
            }
            Toml::InlineTable(table)
        }
        Value::Null => Toml::from(""),
    }
}

fn item(v: &Value) -> Item {
    match v {
        Value::Object(map) => {
            let mut table = Table::new();
            for (k, v) in map {
                table.insert(k, item(v));
            }
            Item::Table(table)
        }
        other => {
            let mut v = value(other);
            if matches!(other, Value::Bool(_)) {
                v.decor_mut().set_suffix(format!(" {MARK}"));
            }
            Item::Value(v)
        }
    }
}

fn is_ours(item: &Item) -> bool {
    if let Some(command) = item.get("command").and_then(Item::as_str) {
        return command == "specforge";
    }
    item.as_value()
        .and_then(|v| v.decor().suffix())
        .and_then(|s| s.as_str())
        .is_some_and(|s| s.contains(MARK))
}

fn same(a: &Item, b: &Item) -> bool {
    let strip = |i: &Item| {
        let mut i = i.clone();
        if let Some(v) = i.as_value_mut() {
            v.decor_mut().clear();
        }
        i.to_string().trim().to_string()
    };
    match (a.as_table(), b.as_table()) {
        (Some(x), Some(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => strip(a) == strip(b),
    }
}

/// The table at `keys` below `doc`, created (implicit) when missing; `Err` names the place where a non-table stands
/// in the way (ADR 0306). The tables it creates are added to `created`.
fn table_at<'a>(
    doc: &'a mut DocumentMut,
    keys: &[String],
    created: &mut Vec<Vec<String>>,
) -> Result<&'a mut Table, String> {
    let mut at = doc.as_table_mut();
    for (n, key) in keys.iter().enumerate() {
        if !at.contains_key(key) {
            let mut t = Table::new();
            t.set_implicit(true);
            at.insert(key, Item::Table(t));
            created.push(keys[..=n].to_vec());
        }
        at = at
            .get_mut(key)
            .and_then(Item::as_table_mut)
            .ok_or_else(|| {
                format!(
                    "'{}' holds a value where install needs a table",
                    keys[..=n].join(".")
                )
            })?;
    }
    Ok(at)
}

/// The tables along `keys` that are left empty, deepest first, go if install `made` them; a table the user keeps
/// something in, or one install did not create, stays.
fn prune_path(doc: &mut DocumentMut, keys: &[String], made: &[Vec<String>]) {
    for depth in (1..=keys.len()).rev() {
        if !made.iter().any(|m| m.as_slice() == &keys[..depth]) {
            continue;
        }
        let mut at = Some(doc.as_table_mut());
        for key in &keys[..depth - 1] {
            at = at.and_then(|t| t.get_mut(key)).and_then(Item::as_table_mut);
        }
        let Some(parent) = at else { continue };
        let key = &keys[depth - 1];
        if parent
            .get(key)
            .and_then(Item::as_table)
            .is_some_and(Table::is_empty)
        {
            parent.remove(key);
        }
    }
}

/// `existing` with the entries of ours replaced by `entries`; see the module docs. `made` are the tables an earlier
/// install created in the file (`[]`: the file itself): an emptied one goes, any other stays; the result's `made` is
/// them and what this merge creates (ADR 0306).
pub fn merge(
    existing: Option<&str>,
    entries: &[MergedEntry],
    scan: &[(&[&str], &str)],
    made: &[Vec<String>],
) -> Result<Merged, String> {
    let source = existing.unwrap_or_default();
    let mut doc: DocumentMut = source.parse().map_err(|e| format!("not TOML: {e}"))?;
    let mut not_rendered = Vec::new();
    // The tables ours may stand in: where the entries go, and where an earlier install put others.
    let mut parents: Vec<Vec<String>> = scan
        .iter()
        .map(|(keys, _)| keys.iter().map(|k| (*k).to_string()).collect())
        .collect();
    for entry in entries {
        if !parents.contains(&entry.keys) {
            parents.push(entry.keys.clone());
        }
    }
    let mut removed_in: Vec<Vec<String>> = Vec::new();
    // Entries of ours the new set no longer holds go.
    for keys in &parents {
        let keys = keys.as_slice();
        let mut walk = Some(doc.as_table_mut());
        for key in keys {
            walk = walk
                .and_then(|t| t.get_mut(key))
                .and_then(Item::as_table_mut);
        }
        if let Some(table) = walk {
            let wanted: Vec<&str> = entries
                .iter()
                .filter(|e| e.keys.as_slice() == keys)
                .filter_map(|e| e.name.as_deref())
                .collect();
            let gone: Vec<String> = table
                .iter()
                .filter(|(k, v)| {
                    is_ours(v)
                        && !wanted.contains(k)
                        && scan.iter().any(|(at, name)| {
                            at.iter().map(|k| (*k).to_string()).eq(keys.iter().cloned())
                                && name == k
                        })
                })
                .map(|(k, _)| k.to_string())
                .collect();
            if !gone.is_empty() {
                removed_in.push(keys.to_vec());
            }
            for k in gone {
                table.remove(&k);
            }
        }
    }
    let mut created: Vec<Vec<String>> = Vec::new();
    for entry in entries {
        let Some(name) = &entry.name else { continue };
        let wanted = item(&entry.value);
        let table = table_at(&mut doc, &entry.keys, &mut created)?;
        match table.get(name) {
            Some(have) if is_ours(have) => {
                if !same(have, &wanted) {
                    table.insert(name, wanted);
                }
            }
            Some(have) if same(have, &wanted) => {}
            Some(_) => not_rendered.push(NotRendered {
                what: format!("{}.{name}", entry.keys.join(".")),
                why: "the file already sets it".into(),
            }),
            None => {
                table.insert(name, wanted);
            }
        }
    }
    for keys in &removed_in {
        prune_path(&mut doc, keys, made);
    }
    let text = doc.to_string();
    let file_made = existing.is_none() || made.iter().any(Vec::is_empty);
    let text = (!text.trim().is_empty() || !file_made).then_some(text);
    let mut made_out = if entries.is_empty() {
        Vec::new()
    } else {
        made.to_vec()
    };
    made_out.extend(created);
    if existing.is_none() && !entries.is_empty() {
        made_out.push(Vec::new());
    }
    made_out.sort();
    made_out.dedup();
    Ok(Merged {
        text,
        not_rendered,
        made: made_out,
    })
}

